from pathlib import Path
import json,html
import numpy as np
from PIL import Image
root=Path('reports/stage-1-final-2026-10-11');before=json.loads((root/'baseline/captures.json').read_text());after=json.loads((root/'acceptance/captures.json').read_text());old={c['file']:c for c in before['captures']};pairs=[];cards=[]
refs={'landing':'01-entrance/irregular-rock-opening.jpeg','tunnel':'02-rocky-graffiti-tunnel/natural-rock-exit-graffiti.jpeg','scaffold':'04-exit-wayfinding/scaffold-sign-and-stage-composition.jpeg','quarry':'03-open-roof-quarry/quarry-open-sky-geometry.jpeg','left':'05-left-right-stalls/festival-stall-lane.jpeg','right':'05-left-right-stalls/tent-vendor-clusters.jpeg','stage':'09-aftermovie/stage-offset-and-wayfinding.jpeg','aerial':'08-aerial-map/aerial-map-markers-layout.jpeg'}
for capture in after['captures']:
 file=capture['file'];baseline=old.get(file)
 if not baseline:continue
 a=np.asarray(Image.open(root/'baseline'/file).convert('RGB')).astype(float);b=np.asarray(Image.open(root/'acceptance'/file).convert('RGB')).astype(float)
 delta=np.abs(a-b);matched=baseline['pose']==capture['pose'] and baseline['viewport']==capture['viewport']
 result={'file':file,'matchedCameraAndViewport':matched,'sameQuality':baseline['snapshot']['quality']==capture['snapshot']['quality'],'sameEffectiveDpr':baseline['stats']['dpr']==capture['stats']['dpr'],'meanAbsoluteRGBDifference':float(delta.mean()),'pixelsAnyChannelDifferenceOver8Percent':float((delta.max(axis=2)>8).mean()*100),'beforePose':baseline['pose'],'afterPose':capture['pose'],'interpretation':'Dynamic stage lights/LED time, draw timing and normal UI state can change pixels; source/config hashes and direct image review determine visual preservation. Not an automatic visual approval.'};pairs.append(result)
 reference=next((v for k,v in refs.items() if k in file),'04-exit-wayfinding/scaffold-sign-and-stage-composition.jpeg')
 cards.append(f'''<article><h2>{html.escape(file)}</h2><p>Camera {html.escape(json.dumps(capture['pose']))}; viewport {html.escape(json.dumps(capture['viewport']))}; quality {capture['snapshot']['quality']}; effective DPR {capture['stats']['dpr']}. Matched pose/view: {matched}. Mean RGB difference {result['meanAbsoluteRGBDifference']:.3f}/255.</p><div class="grid"><figure><img src="baseline/{file}"><figcaption>Current user-approved baseline</figcaption></figure><figure><img src="acceptance/{file}"><figcaption>After technical fixes</figcaption></figure><figure><img src="../../design/references/{reference}"><figcaption>Historical reference; current approved layout takes precedence.</figcaption></figure></div></article>''')
(root/'raw/visual-comparison.json').write_text(json.dumps(pairs,indent=2))
(root/'gallery.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Current approved baseline / Stage 1 acceptance</title><style>body{font:15px/1.5 system-ui;background:#141917;color:#eee;margin:24px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px}figure{margin:0}img{width:100%;max-height:850px;object-fit:contain}article{padding:20px 0;border-top:1px solid #777}a{color:#f3d08a}</style><h1>Gullyverse: current approved baseline and technical acceptance</h1><p>Actual browser captures; fixed registered views are separate from public visitor-journey evidence. Desktop 1366×900, portrait 390×844, requested DPR .25 on SwiftShader. No physical mobile or realism certification. All locked geometry/material/lighting configuration preserved. Animated lights/screens can differ in time. Human visual approval remains with the user.</p><p><a href="baseline/captures.json">Baseline camera metadata</a> · <a href="acceptance/captures.json">Acceptance camera metadata</a> · <a href="raw/visual-comparison.json">Measured differences</a> · <a href="../verification-2026-10-10/recordings/full-journey.webm">Historical actual journey</a> · <a href="../../docs/gullyverse-stage-1-final-acceptance.md">Acceptance report</a></p>'''+''.join(cards)+'''<h2>Previous captures for context</h2><div class="grid"><figure><img src="../verification-2026-10-10/screenshots/05-desktop-hub-arrival-board.png"><figcaption>October 10 hub; different pose/time, not matched baseline.</figcaption></figure><figure><img src="../verification-2026-10-10/screenshots/09-desktop-aftermovie-viewing-area.png"><figcaption>October 10 stage; historical reference only.</figcaption></figure></div></html>''')
print('Compared',len(pairs),'pairs;',sum(c['matchedCameraAndViewport'] for c in pairs),'matched cameras/viewports.')
